  public I next() {
    if (inner == null) {
      throw new java.util.NoSuchElementException();
    }
    Iterator<? extends I> nonNullInner = inner;
    I result = nonNullInner.next();
    if (!nonNullInner.hasNext()) {
      advanceOuter();
    }
    return result;
  }
